"""Capacity & doubling law: |{0,1}^N| = 2^N, each neuron doubles capacity."""
from __future__ import annotations
from itertools import product

def capacity(n: int) -> int:
    return 2 ** n

def brute_force_count(n: int) -> int:
    return sum(1 for _ in product((0, 1), repeat=n))

def main() -> None:
    for n in range(1, 11):
        assert brute_force_count(n) == capacity(n)
        ratio = capacity(n) // capacity(n - 1)
        print(f"N={n:2d}  capacity=2^N={capacity(n):5d}  doubling ratio={ratio}")
    print(f"N=300 -> {capacity(300):.3e} distinct codes")

if __name__ == "__main__":
    main()

"""Sparse efficiency: info per spike rho(N,k)=log2 C(N,k)/k peaks at one-hot."""
from __future__ import annotations
from math import comb, log2

def info_per_spike(n: int, k: int) -> float:
    return 0.0 if k == 0 else log2(comb(n, k)) / k

def optimal_sparsity(n: int) -> tuple[int, float]:
    best = max(range(1, n + 1), key=lambda k: info_per_spike(n, k))
    return best, info_per_spike(n, best)

def main() -> None:
    n = 10000
    for k in (1, 2, 10, 100, n // 100, n // 2):
        print(f"k={k:6d}  rho={info_per_spike(n, k):8.3f} bits/spike")
    k_star, rho_star = optimal_sparsity(n)
    print(f"optimal k*={k_star} (one-hot), rho*={rho_star:.3f}=log2 N")
    print(f"dense floor = 2 bits/spike; advantage factor = {rho_star/2:.2f}x")

if __name__ == "__main__":
    main()

