from __future__ import annotations

def capacity(n: int) -> int:
    """Representational capacity of n binary neurons.

    Returns 2**n and (implicitly) satisfies the doubling recurrence
    capacity(n) == 2 * capacity(n - 1) for n >= 1.
    """
    return 1 << n  # exact big-integer 2**n

def verify_doubling(max_n: int = 64) -> bool:
    return all(capacity(n) == 2 * capacity(n - 1) for n in range(1, max_n + 1))

